import{_ as s,o as n,c as a,a2 as t}from"./chunks/framework.KobcctIO.js";const m=JSON.parse('{"title":"Modules Natifs Gens-Core (Zéro Dépendance)","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/dev/native-modules.md","filePath":"fr/guide/dev/native-modules.md"}'),i={name:"fr/guide/dev/native-modules.md"};function o(r,e,c,l,d,p){return n(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="modules-natifs-gens-core-zero-dependance" tabindex="-1">Modules Natifs Gens-Core (Zéro Dépendance) <a class="header-anchor" href="#modules-natifs-gens-core-zero-dependance" aria-label="Permalink to &quot;Modules Natifs Gens-Core (Zéro Dépendance)&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/D%C3%A9pendances-0%25%20Bloatware-green.svg" alt="Dépendances"><img src="https://img.shields.io/badge/Modules-100%25%20In--House-blue.svg" alt="Modules"><img src="https://img.shields.io/badge/S%C3%A9curit%C3%A9-Surface%20d&#39;Attaque%20Minimale-orange.svg" alt="Sécurité"></div><p>Afin de réduire drastiquement le poids de l&#39;exécutable, d&#39;accélérer les temps de chargement et de supprimer les vulnérabilités liées à la chaîne d&#39;approvisionnement (<em>Supply Chain Attacks</em>), Gens-Launcher bannit les bibliothèques tierces volumineuses au profit de modules <strong>100% natifs développés en interne</strong>.</p><hr><h2 id="_1-module-discord-rich-presence-natif-discord-js" tabindex="-1">1. Module Discord Rich Presence Natif (<code>discord.js</code>) <a class="header-anchor" href="#_1-module-discord-rich-presence-natif-discord-js" aria-label="Permalink to &quot;1. Module Discord Rich Presence Natif (\`discord.js\`)&quot;">​</a></h2><p>Plutôt que d&#39;importer <code>@xhayper/discord-rpc</code> ou le SDK Discord officiel (qui pèsent plusieurs mégaoctets et multiplient les dépendances transitives), Gens-Launcher intègre son propre client RPC basé sur les <strong>Named Pipes</strong> du système d&#39;exploitation :</p><ul><li><strong>Protocole Bas Niveau :</strong><ul><li><strong>Windows :</strong> Connexion directe sur <code>\\\\?\\pipe\\discord-ipc-0</code>.</li><li><strong>Linux / macOS :</strong> Connexion par socket Unix sur <code>$XDG_RUNTIME_DIR/discord-ipc-0</code> ou <code>/tmp/discord-ipc-0</code>.</li></ul></li><li><strong>Analyseur de Trame Binaire (IPC Framer) :</strong> Encode et décode les opcodes RPC (<code>HANDSHAKE = 0</code>, <code>FRAME = 1</code>, <code>CLOSE = 2</code>, <code>PING = 3</code>, <code>PONG = 4</code>) directement avec des Buffers natifs Node.js.</li><li><strong>Rate-Limiter Intégré :</strong> Empêche tout dépassement des quotas d&#39;événements de l&#39;API Discord.</li><li><strong>Gestion Stricte du Mode Hors-Ligne :</strong> Lorsque l&#39;application démarre sans connexion Internet, <code>discord.js</code> consulte localement <code>settings.json</code> et coupe toute tentative de socket en boucle pour éviter la création de processus zombies.</li></ul><hr><h2 id="_2-analyseur-et-constructeur-binaire-nbt-nbt-js" tabindex="-1">2. Analyseur et Constructeur Binaire NBT (<code>nbt.js</code>) <a class="header-anchor" href="#_2-analyseur-et-constructeur-binaire-nbt-nbt-js" aria-label="Permalink to &quot;2. Analyseur et Constructeur Binaire NBT (\`nbt.js\`)&quot;">​</a></h2><p>Le format NBT (<em>Named Binary Tag</em>) est le standard binaire utilisé par Minecraft pour stocker les mondes, les inventaires et la liste des serveurs multijoueur (<code>servers.dat</code>).</p><p>Gens-Launcher remplace <code>prismarine-nbt</code> par une implémentation légère basée sur l&#39;API native <code>node:zlib</code> :</p><ul><li><strong>Compression GZIP / ZLIB :</strong> Détection automatique de l&#39;en-tête de compression ou lecture non compressée.</li><li><strong>Types Supportés :</strong> TAG_End (0), TAG_Byte (1), TAG_Short (2), TAG_Int (3), TAG_Long (4), TAG_Float (5), TAG_Double (6), TAG_Byte_Array (7), TAG_String (8), TAG_List (9), TAG_Compound (10), TAG_Int_Array (11), TAG_Long_Array (12).</li><li><strong>Prise en charge des BigInt :</strong> Manipulation sans perte des entiers 64 bits (<code>TAG_Long</code>).</li><li><strong>Édition Sécurisée de <code>servers.dat</code> :</strong> Permet à l&#39;interface de lire, réordonner et insérer des serveurs favoris sans jamais corrompre la structure du fichier du joueur.</li></ul><hr><h2 id="_3-authentification-microsoft-native-auth-js" tabindex="-1">3. Authentification Microsoft Native (<code>auth.js</code>) <a class="header-anchor" href="#_3-authentification-microsoft-native-auth-js" aria-label="Permalink to &quot;3. Authentification Microsoft Native (\`auth.js\`)&quot;">​</a></h2><p>L&#39;authentification officielle Microsoft a été réécrite de zéro pour se dispenser de bibliothèques tierces :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ Étape 1 : Device Code ]</span></span>
<span class="line"><span>POST https://login.microsoftonline.com/consumers/oauth2/v2.0/devicecode</span></span>
<span class="line"><span>  -&gt; Obtention de user_code et verification_uri</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[ Étape 2 : Polling du Jeton OAuth2 ]</span></span>
<span class="line"><span>POST https://login.microsoftonline.com/consumers/oauth2/v2.0/token</span></span>
<span class="line"><span>  -&gt; Obtention du refresh_token et access_token</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[ Étape 3 : Authentification Xbox Live (XBL) ]</span></span>
<span class="line"><span>POST https://user.auth.xboxlive.com/user/authenticate</span></span>
<span class="line"><span>  -&gt; Obtention du token XBL et du UserHash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[ Étape 4 : Autorisation XSTS (Minecraft Services) ]</span></span>
<span class="line"><span>POST https://xsts.auth.xboxlive.com/xsts/authorize</span></span>
<span class="line"><span>  -&gt; Obtention du token XSTS</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[ Étape 5 : Jeton d&#39;Accès Minecraft ]</span></span>
<span class="line"><span>POST https://api.minecraftservices.com/authentication/login_with_xbox</span></span>
<span class="line"><span>  -&gt; Obtention du bearer token Minecraft officiel</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[ Étape 6 : Profil Joueur &amp; UUID ]</span></span>
<span class="line"><span>GET https://api.minecraftservices.com/minecraft/profile</span></span>
<span class="line"><span>  -&gt; Récupération de l&#39;UUID officiel, du pseudonyme et des skins/capes</span></span></code></pre></div><ul><li><strong>Sécurité :</strong> Tous les flux transitent exclusivement via HTTPS avec validation stricte des certificats TLS.</li><li><strong>Rafraîchissement Silencieux :</strong> Le <code>refresh_token</code> est stocké chiffré et renouvelé en arrière-plan sans interrompre l&#39;expérience de jeu.</li></ul><hr><h2 id="_4-moteur-de-lancement-src-gens-core-components-launcher-js" tabindex="-1">4. Moteur de Lancement (<code>src/gens-core/components/launcher.js</code>) <a class="header-anchor" href="#_4-moteur-de-lancement-src-gens-core-components-launcher-js" aria-label="Permalink to &quot;4. Moteur de Lancement (\`src/gens-core/components/launcher.js\`)&quot;">​</a></h2><p>Le lanceur prépare et exécute le processus Java de Minecraft :</p><ul><li><strong>Vérification d&#39;Intégrité :</strong> Chaque bibliothèque (.jar) et asset est comparé à son empreinte SHA-1 officielle avant exécution.</li><li><strong>Assemblage du Classpath :</strong> Construction dynamique du paramètre <code>-cp</code> avec séparateur natif (<code>;</code> sous Windows, <code>:</code> sous Linux/macOS).</li><li><strong>Extraction des Bibliothèques Natives :</strong> Extraction des fichiers <code>.dll</code>, <code>.so</code> ou <code>.dylib</code> dans un dossier temporaire isolé nettoyé à la fermeture.</li><li><strong>Exécution Sécurisée :</strong> Utilisation stricte de <code>child_process.execFile</code> (et non <code>exec</code>), garantissant l&#39;impossibilité d&#39;injecter des commandes shell arbitraires via les arguments JVM ou les noms d&#39;instance.</li></ul>`,21)])])}const h=s(i,[["render",o]]);export{m as __pageData,h as default};
